'use strict';
let meetingRoutes=[],meetingGeneration=0,meetingPainter=null;
const routeModes=[['Transfer','公交地铁'],['Driving','驾车'],['Walking','步行']];
const meetingSaved=read('travel-meeting',{});
function refreshMeetingPlaces(){const select=$('meeting-point'),previous=select.value||meetingSaved.point;select.replaceChildren();const placeholder=document.createElement('option');placeholder.value='';placeholder.textContent='选择已标记的集合点';select.append(placeholder);points.filter(p=>p.lng!==null).forEach(p=>{const o=document.createElement('option');o.value=p.id;o.textContent=p.name;select.append(o)});if(points.some(p=>p.id===previous&&p.lng!==null))select.value=previous;refreshMeetingSummary()}
function meetingTimestamp(text){return new Date(text+'+08:00').getTime()}
function cityFromAddress(text){const m=String(text||'').match(/(?:北京市|上海市|天津市|重庆市|[^省自治区\s]{2,}市)/);return m?m[0]:''}
function deriveCity(target,members){for(const p of [target,...members]){const c=cityFromAddress(p.address);if(c)return c}return new Promise(resolve=>{const timer=setTimeout(()=>resolve(''),8000);try{new AMap.Geocoder().getAddress([target.lng,target.lat],(status,result)=>{clearTimeout(timer);const ac=result?.regeocode?.addressComponent||{};resolve(cityFromAddress(ac.city)||cityFromAddress(ac.province))})}catch{clearTimeout(timer);resolve('')}})}
function departureTime(arrival,seconds){return arrival-Math.ceil(seconds/60)*60000}
function formatMeetingTime(timestamp){return new Intl.DateTimeFormat('zh-CN',{timeZone:'Asia/Shanghai',month:'numeric',day:'numeric',hour:'2-digit',minute:'2-digit',hour12:false}).format(new Date(timestamp))}
function loadRoutePlugins(){return new Promise((resolve,reject)=>{const timer=setTimeout(()=>reject(Error('路线服务加载超时，请检查网络')),15000);AMap.plugin(['AMap.Transfer','AMap.Driving','AMap.Walking'],()=>{clearTimeout(timer);resolve()})})}
function queryMeetingRoute(mode,origin,destination,city){return new Promise(resolve=>{let service;const timer=setTimeout(()=>{service?.clear();resolve({error:'查询超时'})},15000);try{const options=mode==='Transfer'?{city,cityd:city,policy:AMap.TransferPolicy.LEAST_TIME}:{ };service=new AMap[mode](options);service.search([origin.lng,origin.lat],[destination.lng,destination.lat],(status,result)=>{clearTimeout(timer);const route=mode==='Transfer'?result?.plans?.[0]:result?.routes?.[0];service.clear();if(status!=='complete'||!route||!Number.isFinite(Number(route.time)))resolve({error:status==='no_data'?'未找到可用路线':'路线查询失败，请检查服务权限或稍后重试'});else resolve({seconds:Number(route.time),distance:Number(route.distance)||0})})}catch{clearTimeout(timer);service?.clear();resolve({error:'路线服务不可用'})}})}
function clearMeetingRoute(){if(meetingPainter){meetingPainter.clear();meetingPainter=null}}
function drawMeetingRoute(item){clearMeetingRoute();const options={map,autoFitView:true,hideMarkers:false};if(item.mode==='Transfer')Object.assign(options,{city:item.city,cityd:item.city,policy:AMap.TransferPolicy.LEAST_TIME});meetingPainter=new AMap[item.mode](options);meetingPainter.search([item.origin.lng,item.origin.lat],[item.destination.lng,item.destination.lat],(status)=>{if(status!=='complete')toast('路线绘制失败，请重新查询')})}
function invalidateMeeting(){meetingGeneration++;meetingRoutes=[];clearMeetingRoute();$('meeting-results').replaceChildren();$('meeting-plan').disabled=false;}
function saveMeeting(){try{localStorage.setItem('travel-meeting',JSON.stringify({point:$('meeting-point').value,time:$('meeting-time').value}))}catch{toast('集合设置未能保存，请检查浏览器存储')}}
$('meeting-time').value=typeof meetingSaved.time==='string'?meetingSaved.time:'';
for(const id of ['meeting-point','meeting-time'])$(id).onchange=()=>{invalidateMeeting();saveMeeting();refreshMeetingSummary()};
$('meeting-form').onsubmit=async e=>{e.preventDefault();if(!map){toast('请先连接高德地图');openConfig();return}const target=points.find(p=>p.id===$('meeting-point').value&&p.lng!==null);if(!target){toast('请选择带有坐标的集合点');return}const arrival=meetingTimestamp($('meeting-time').value);if(!Number.isFinite(arrival)||arrival<=Date.now()){toast('请选择未来的集合日期和时间（北京时间）');return}const members=points.filter(p=>p.type==='friend'&&p.id!==target.id);if(!members.length){toast('请先添加你和同伴的位置，类型选择「同伴」');return}const city=await deriveCity(target,members);if(!city){toast('未能识别集合城市，请为集合点或同伴补充带城市的地址');return}invalidateMeeting();const generation=meetingGeneration;saveMeeting();$('meeting-plan').disabled=true;$('meeting-results').textContent='正在分别查询大家的路线…';try{await loadRoutePlugins();const results=[];for(const origin of members){if(generation!==meetingGeneration)return;if(origin.lng===null){results.push({origin,error:'缺少坐标，请先编辑位置'});continue}for(const [mode,label] of routeModes){const estimate=await queryMeetingRoute(mode,origin,target,city);if(generation!==meetingGeneration)return;results.push({origin,destination:target,mode,label,city,...estimate})}}meetingRoutes=results;const box=$('meeting-results');box.replaceChildren();for(const origin of members){const section=document.createElement('article');section.className='meeting-member';const heading=document.createElement('h3');heading.textContent=origin.name;section.append(heading);results.filter(r=>r.origin.id===origin.id).forEach(item=>{const row=document.createElement('div');row.className='meeting-route';if(item.error){row.textContent=(item.label?item.label+'：':'')+item.error;row.classList.add('hint')}else{const depart=departureTime(arrival,item.seconds),summary=document.createElement('p');summary.innerHTML=`<strong>${item.label}</strong> · 约${Math.ceil(item.seconds/60)}分钟<br>建议 ${escapeHTML(formatMeetingTime(depart))} 出发${depart<=Date.now()?' <span class="late">出发时间已过</span>':''}`;row.append(summary);const button=document.createElement('button');button.type='button';button.textContent='查看路线';button.onclick=()=>drawMeetingRoute(item);row.append(button)}section.append(row)});box.append(section)}const note=document.createElement('p');note.className='hint';note.textContent=`集合：${formatMeetingTime(arrival)}（北京时间）。出发时间按本次查询耗时倒推，非未来时刻表或路况预测，出发前请重新查询。`;box.append(note)}catch(err){if(generation===meetingGeneration)$('meeting-results').textContent=err.message}finally{if(generation===meetingGeneration)$('meeting-plan').disabled=false}};
$('clear-route').onclick=clearMeetingRoute;
$('meeting-open').onclick=()=>$('meeting').showModal();
function refreshMeetingSummary(){const p=points.find(x=>x.id===$('meeting-point').value&&x.lng!==null);const time=$('meeting-time').value;$('meeting-summary').textContent=p||time?`${p?p.name:'未选集合点'}${time?' · '+time.replace('T',' '):''}（北京时间）`:'尚未设置集合点和时间';}
const originalRender=render;render=function(){originalRender();refreshMeetingPlaces();invalidateMeeting()};
refreshMeetingPlaces();
